        info.GetReturnValue().Set(buffer);
	}
	else
	{
		Local<Value> bin_value = Nan::Encode(serialized_object, object_size, (Nan::Encoding)BINARY)->ToString();
		free(serialized_object);
        info.GetReturnValue().Set(bin_value);
	}
