inline void obj_new_property(v8::Isolate* isolate, v8::Local<v8::Object>& obj, const char* key, char* v) {
	obj->CreateDataProperty(isolate->GetCurrentContext(), Cast_Key(new_value(isolate, key)), new_value(isolate, v));
}

inline void obj_new_property(v8::Isolate* isolate, v8::Local<v8::Object>& obj, const char* key, const std::string& v) {
	obj->CreateDataProperty(isolate->GetCurrentContext(), Cast_Key(new_value(isolate, key)), new_value(isolate, v));
}

inline void obj_new_property(v8::Isolate* isolate, v8::Local<v8::Object>& obj, const char* key, std::vector<unsigned char>& v) {
	v8::Local<v8::ArrayBuffer> buff = v8::ArrayBuffer::New(isolate, v.data(), v.size());
	v8::Local<v8::Uint8Array> dataarray = v8::Uint8Array::New(buff, 0, v.size());
	obj->CreateDataProperty(isolate->GetCurrentContext(), Cast_Key(new_value(isolate, key)), dataarray);
}

